def fit(teachers, record_return=None):
    views = [base.prepare_input(pair["input"]) for pair in teachers]
    evaluators = [Evaluator(view) for view in views]
    retained = []
    for number, program in enumerate(all_programs()):
        results = [evaluator.evaluate(program) for evaluator in evaluators]
        exacts = [result["failure"] is None and result["output"] == pair["output"]
                  for result, pair in zip(results, teachers)]
        if record_return is not None:
            record_return(number, program, results, exacts)
        if teachers and all(exacts):
            retained.append(program)
    return retained, views

def mixed_region_dicts_for_grid(
    grid: Grid,
    background_color: int,
    include_diagonal: bool = True,
) -> list[dict[str, Any]]:
    return [
        mixed_region_dict_from_feature_record(record)
        for record in _mixed_region_feature_records(
            grid_key(grid),
            int(background_color),
            bool(include_diagonal),
        )
    ]

def transform_grid_by_name(grid: Grid, transform_name: str) -> Grid | None:
    if transform_name == "identity":
        return clone_grid(grid)
    if transform_name == "rot90":
        return [list(row) for row in zip(*grid[::-1])]
    if transform_name == "rot180":
        return [row[::-1] for row in grid[::-1]]
    if transform_name == "rot270":
        return [list(row) for row in zip(*grid)][::-1]
    if transform_name == "flip_h":
        return [row[::-1] for row in grid]
    if transform_name == "flip_v":
        return grid[::-1]
    if transform_name == "transpose":
        return [list(row) for row in zip(*grid)]
    if transform_name == "anti_transpose":
        return [list(row) for row in zip(*[row[::-1] for row in grid[::-1]])]
    return None

def component_hole_count(component: dict[str, Any]) -> int:
    row_min, col_min, row_max, col_max = component["bbox"]
    height = row_max - row_min + 1
    width = col_max - col_min + 1
    mask = component_relative_mask(component)
    seen: set[Cell] = set()
    hole_count = 0
    for row in range(height):
        for col in range(width):
            if (row, col) in mask or (row, col) in seen:
                continue
            queue: deque[Cell] = deque([(row, col)])
            seen.add((row, col))
            touches_border = False
            while queue:
                current_row, current_col = queue.popleft()
                if current_row in (0, height - 1) or current_col in (0, width - 1):
                    touches_border = True
                for row_delta, col_delta in ORTHOGONAL_DELTAS:
                    next_row = current_row + row_delta
                    next_col = current_col + col_delta
                    next_cell = (next_row, next_col)
                    if not (0 <= next_row < height and 0 <= next_col < width):
                        continue
                    if next_cell in seen or next_cell in mask:
                        continue
                    seen.add(next_cell)
                    queue.append(next_cell)
            if not touches_border:
                hole_count += 1
    return hole_count

def collapse(records):
    failures = [record["failure"] for record in records if record["failure"]]
    outputs = []
    for record in records:
        for result in record["alternatives"]:
            if result["failure"]:
                failures.append(result["failure"])
            else:
                outputs.append(result["output"])
    if failures:
        return None, {"kind": "unresolved", "code": "one_or_more_hypotheses_failed", "failures": failures}
    if not outputs:
        return None, {"kind": "role", "code": "no_rendered_hypotheses"}
    if len({grid_key(out) for out in outputs}) != 1:
        return None, {"kind": "ambiguity", "code": "role_or_order_disagreement"}
    return outputs[0], None

def apply_retained(programs, grid):
    view = base.prepare_input(grid)
    evaluator = Evaluator(view)
    returns = [{"program": program.record(), "result": evaluator.evaluate(program)} for program in programs]
    failures = [i for i, row in enumerate(returns) if row["result"]["failure"]]
    success = [row["result"]["output"] for row in returns if row["result"]["failure"] is None]
    unique = {base.grid_key(output) for output in success}
    if not programs:
        status, code = "HOLD", "no_teacher_consistent_program"
    elif failures:
        status, code = "HOLD", "retained_program_failure"
    elif len(unique) != 1:
        status, code = "HOLD", "retained_program_disagreement"
    else:
        status, code = "OUTPUT", None
    return {"status": status, "code": code, "output": success[0] if status == "OUTPUT" else None,
            "failure_program_indices": failures, "distinct_success_outputs": len(unique),
            "input_view": view, "returns": returns}
